// Authored content for 3.2.1.2 Lifestyle, coronary heart disease and cancer (OxfordAQA 9610 v5.1, printed p.22;
// statements 3.2.1.2.s1–s3 in data/spec.js). Official wording: "Specific risk factors are associated with coronary
// heart disease and cancer. Changes in lifestyle may be associated with a reduced risk of contracting these
// conditions. Students should be able to analyse, interpret and evaluate data associated with specific risk factors
// and the incidence of disease." Atheroma and myocardial infarction are 3.2.7 and tumour biology is 3.2.11: both are
// cross-referenced only. No genetics is required ("genes" in the topic title has no examinable statement).
// REAL data come from B.diseaseModel (data/content/_disease-art.js), with the source and year shown on the page and
// collected in SOURCES below; HYPOTHETICAL data are labelled so wherever they appear. Every number quoted in a
// question is computed from the model here and was checked by hand (3.2.1 author report).
// Interactives: disRiskData (Risk Factor Data Investigator) and disEpi (Epidemiology Challenge).
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.diseaseArt, M = window.BIO.diseaseModel, D = M.DOLL, SRC = M.SRC;
  const R = "3.2.1.2";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot) => window.BIO.views.photo(slot);
  const f = M.fix;
  const tbl = (head, rows, cls = "") => `<table class="tbl ${cls}"><thead><tr>${head.map((x) => `<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const cite = (k) => `<span class="tiny muted">Source: <a href="${SRC[k].url}" target="_blank" rel="noopener">${SRC[k].short}</a></span>`;
  const SC = `<span class="badge navy" title="beyond the specification: an example, not something to learn">stretch and challenge</span>`;
  const HYP = `<span class="badge amber">hypothetical data</span>`, REAL = (k) => `<span class="badge teal">real data</span> ${cite(k)}`;

  // ---- worked values (each checked by hand; see the author report) ----
  const nv = M.dollRow("never"), fo = M.dollRow("former"), cu = M.dollRow("current"), c1 = M.dollRow("c1"), c15 = M.dollRow("c15"), c25 = M.dollRow("c25");
  const lungRR = f(cu.lung / nv.lung, 1), lungRR2 = f(+f(cu.lung / nv.lung, 2), 1), ihdPct2 = f((+f(cu.ihd / nv.ihd, 2) - 1) * 100, 1), ihdRR = f(cu.ihd / nv.ihd, 2), allRR = f(cu.all / nv.all, 2);
  const lungAbs = f(cu.lung - nv.lung, 2), ihdAbs = f(cu.ihd - nv.ihd, 2), ihdPct = f(M.pctChange(nv.ihd, cu.ihd), 1);
  const dose = f(c25.lung / c1.lung, 2), formerLower = f(100 * (cu.lung - fo.lung) / cu.lung, 1);
  const PR = M.PETO.rows, cont = PR[0].risk, red = (k) => f(100 * (cont - PR[k].risk) / cont, 1), absd = (k) => f(cont - PR[k].risk, 1);
  const CO = M.COFFEE, crudeC = M.rate(CO.crude.coffee.cases, CO.crude.coffee.n), crudeN = M.rate(CO.crude.none.cases, CO.crude.none.n);
  const SA = M.SAMPLE, sS = { a: M.pctOf(SA.small.active.cases, SA.small.active.n), i: M.pctOf(SA.small.inactive.cases, SA.small.inactive.n) }, sL = { a: M.pctOf(SA.large.active.cases, SA.large.active.n), i: M.pctOf(SA.large.inactive.cases, SA.large.inactive.n) };
  const G = M.GYM, gM = M.pctOf(G.members.cases, G.members.n), gN = M.pctOf(G.non.cases, G.non.n);
  const RA = M.RELABS, raE = Math.round(RA.base * RA.rr);
  const whoAS = f(M.WHO.deathsM * M.WHO.pctAttackStroke / 100, 1);
  const check = (c, m) => { if (!c) console.warn("3.2.1.2 data check failed:", m); };
  check(lungRR === "14.6" && ihdRR === "1.62" && lungAbs === "2.32" && ihdAbs === "3.82" && ihdPct === "61.7" && dose === "3.18" && formerLower === "72.7" && allRR === "1.83", "Doll values");
  check(red(2) === "62.3" && red(4) === "89.3" && red(1) === "37.7" && f(crudeC, 1) === "7.0" && f(crudeN, 2) === "2.33" && f(crudeC / crudeN, 1) === "3.0" && whoAS === "16.8" && raE === 59, "Peto, coffee, WHO, relabs values");

  const dollTable = () => tbl(["Smoking habit (men)", "Lung cancer", "Ischaemic heart disease", "All causes"], D.rows.map((r) => [r.label, r.lung.toFixed(2), r.ihd.toFixed(2), r.all.toFixed(2)]));
  const SOURCES = `<p class="tiny muted"><strong>Sources of real data</strong> (each checked on 5 November 2026): ${["who", "brown", "interheart", "lewington", "doll", "peto", "iarc", "biobank"].map((k) => `<a href="${SRC[k].url}" target="_blank" rel="noopener">${SRC[k].cite}</a>`).join("; ")}. All other datasets on this page are hypothetical and labelled.</p>`;

  // ---------------------------------------------------------------- C. Risk Factor Data Investigator ----------------------------------------------------------------
  const inv = { kind: "disRiskData", title: "Risk Factor Data Investigator", note: "Five datasets: three real (with sources) and two hypothetical. Switch between rates, relative risk and excess risk, reveal hidden variables and change sample sizes; every number shown is calculated on the page from the data. Answer the questions under each dataset (marked and recorded).",
    items: [
      { id: "doll", label: "Smoking and deaths", tag: "real", title: "Male British doctors, 1951–2001",
        intro: `In 1951, ${D.n.toLocaleString("en-GB")} male doctors in the UK reported their smoking habits and were followed for 50 years (a prospective cohort study). The table gives death rates per 1000 men per year, standardised for age.`,
        questions: [
          { id: `q-${R}-iv1`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Doll data. Use the 'relative to non-smokers' view or calculate it yourself. Give each answer to the number of decimal places shown.", text: "Lung cancer: current smokers' rate ÷ non-smokers' rate = {{1}} (1 d.p.). Ischaemic heart disease: {{2}} (2 d.p.).", answers: { 1: [...new Set([lungRR, lungRR2])], 2: [ihdRR] }, explanation: `Lung cancer: ${cu.lung.toFixed(2)} ÷ ${nv.lung.toFixed(2)} = ${f(cu.lung / nv.lung, 3)}, which is ${lungRR} to 1 d.p. The interactive shows ${f(cu.lung / nv.lung, 2)} (2 d.p.), and rounding that again gives ${lungRR2}; both answers are accepted, but round only once, from the unrounded value, where you can. IHD: ${cu.ihd.toFixed(2)} ÷ ${nv.ihd.toFixed(2)} = ${ihdRR}.` },
          { id: `q-${R}-iv2`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Doll data. Switch to 'excess over non-smokers'.", text: "Extra deaths per 1000 current smokers per year, compared with non-smokers: lung cancer {{1}}; ischaemic heart disease {{2}}.", answers: { 1: [lungAbs], 2: [ihdAbs] }, explanation: `Lung cancer: ${cu.lung} − ${nv.lung} = ${lungAbs}. IHD: ${cu.ihd} − ${nv.ihd} = ${ihdAbs}.` },
          { id: `q-${R}-iv3`, ref: R, stmts: S(1, 3), type: "mcq", marks: 1, stem: "Doll data. Smoking multiplies the lung cancer death rate far more than the IHD death rate, yet it is linked with more extra deaths from IHD. Why?", options: ["IHD is much more common, so a smaller relative increase adds more deaths", "The IHD data are less reliable", "Smokers stop dying of lung cancer after 50 years", "The lung cancer rates were not standardised for age"], answer: 0, explanation: `The baseline IHD rate (${nv.ihd} per 1000) is far higher than for lung cancer (${nv.lung}), so a ${ihdRR}-fold rise adds ${ihdAbs} deaths per 1000 per year, against ${lungAbs} for lung cancer. Relative and absolute measures answer different questions.` },
          { id: `q-${R}-iv4`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Doll data. Which feature of the data most strongly supports a causal link between smoking and lung cancer, rather than only an association?", options: [`A dose–response: the rate rises from ${c1.lung} to ${c15.lung} to ${c25.lung} per 1000 as cigarettes per day increase`, "Doctors were chosen because they are a well-educated group", "Lung cancer caused fewer deaths than IHD", "The study lasted 50 years, so some men died of other causes"], answer: 0, explanation: "A dose–response relationship is one of the strongest pieces of evidence for cause (with a plausible mechanism, a consistent finding in other studies and a fall in risk after stopping). It still does not prove cause on its own." },
        ] },
      { id: "peto", label: "Stopping smoking", tag: "real", title: "UK men: risk of death from lung cancer by age 75",
        intro: "National death rates combined with two case-control studies were used to estimate the cumulative risk of dying from lung cancer by age 75 (ignoring other causes of death) for UK men at 1990 rates, by the age at which they stopped smoking.",
        questions: [
          { id: `q-${R}-iv5`, ref: R, stmts: S(2, 3), type: "gap", marks: 2, stem: "Stopping-smoking data. Choose 'stopped at about 50' and compare it with continued smoking. Give answers to 1 d.p.", text: "Absolute reduction in risk: {{1}} percentage points. Percentage reduction relative to continued smoking: {{2}} %.", answers: { 1: [absd(2)], 2: [red(2), f(100 * (cont - PR[2].risk) / cont, 0)] }, explanation: `${cont} − ${PR[2].risk.toFixed(1)} = ${absd(2)} percentage points; ${absd(2)} ÷ ${cont} × 100 = ${red(2)} %.` },
          { id: `q-${R}-iv6`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: "Stopping-smoking data. Which conclusion is best supported?", options: ["For UK men in this study, stopping at any of the ages shown was associated with a lower risk than continuing, and stopping earlier with a lower risk still", "Stopping at 30 removes all risk of lung cancer", "A man who stops at 50 will not die of lung cancer", "Stopping smoking has no effect after the age of 40"], answer: 0, explanation: `Even stopping at about 30 leaves a risk (${PR[4].risk.toFixed(1)} %) above that of lifelong non-smokers (below 1 %). Population estimates cannot say what will happen to one man.` },
        ] },
      { id: "interheart", label: "Heart attack risk factors", tag: "real", title: "INTERHEART: first heart attacks in 52 countries",
        intro: `A case-control study compared ${M.INTERHEART.cases.toLocaleString("en-GB")} people who had had a first heart attack (cases) with ${M.INTERHEART.controls.toLocaleString("en-GB")} people of similar age and sex who had not (controls), in ${M.INTERHEART.countries} countries. An odds ratio above 1 means the factor was more common among cases; below 1, less common.`,
        questions: [
          { id: `q-${R}-iv7`, ref: R, stmts: S(3, 2), type: "mcq", marks: 1, stem: "INTERHEART. Daily consumption of fruit and vegetables had an odds ratio of 0.70. What does this mean?", options: ["People who ate fruit and vegetables daily had about 30 % lower odds of having had a heart attack than those who did not", "Eating fruit and vegetables daily prevents 70 % of heart attacks", "70 % of the cases ate fruit and vegetables daily", "Fruit and vegetables have no association with heart attacks"], answer: 0, explanation: "An odds ratio of 0.70 is a 30 % lower odds. It shows an association; people who eat more fruit and vegetables may also differ in other ways (confounding)." },
          { id: `q-${R}-iv8`, ref: R, stmts: S(1, 3), type: "short", marks: 3, stem: "INTERHEART. Current smoking had an odds ratio of 2.87 and a history of high blood pressure 1.91. Evaluate the claim that 'smoking is a bigger risk factor for heart attacks than high blood pressure'. (3 marks)", scheme: [{ point: "Supported by the data: the odds ratio for smoking (2.87) is higher than for high blood pressure (1.91)", marks: 1 }, { point: "Limitation: case-control data: exposure recalled or recorded after the event / association, not proof of cause / possible confounding", marks: 1 }, { point: "Limitation: odds ratios compare groups; the effect on the population also depends on how common each factor is; or 'history of high blood pressure' depends on diagnosis", marks: 1 }], model: "The data support the claim for this study: the odds ratio for current smoking (2.87) is higher than for a history of high blood pressure (1.91), so smoking was more strongly associated with having had a heart attack. However, this is a case-control study: information about exposure was collected after the heart attack, so recall may be biased, and it shows association rather than proving cause. The total effect on a population also depends on how common each factor is, and 'history of high blood pressure' depends on people having been diagnosed, so some cases may have been missed.", commonErrors: "Treating the odds ratio as a percentage of heart attacks caused." },
        ] },
      { id: "coffee", label: "Confounding", tag: "hypothetical", title: "Coffee drinking and lung cancer (hypothetical)",
        intro: "A hypothetical cohort of 20,000 adults recorded coffee drinking and was followed for 10 years. First look at everyone together, then split the data by smoking.",
        questions: [
          { id: `q-${R}-iv9`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Confounding data (hypothetical), everyone together. Give rates per 1000 to the decimal places shown.", text: "Lung cancer rate in coffee drinkers: {{1}} per 1000 (1 d.p.). In non-coffee drinkers: {{2}} per 1000 (2 d.p.).", answers: { 1: [f(crudeC, 1), "7"], 2: [f(crudeN, 2)] }, explanation: `${CO.crude.coffee.cases} ÷ ${CO.crude.coffee.n.toLocaleString("en-GB")} × 1000 = ${f(crudeC, 1)}; ${CO.crude.none.cases} ÷ ${CO.crude.none.n.toLocaleString("en-GB")} × 1000 = ${f(crudeN, 2)}. Coffee drinkers appear to have ${f(crudeC / crudeN, 1)} times the rate.` },
          { id: `q-${R}-iv10`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Confounding data (hypothetical). After splitting by smoking, coffee drinkers and non-drinkers have the same rate within each group. What explains the apparent link?", options: ["Smoking is a confounder: coffee drinkers were more likely to smoke, and smoking is linked with lung cancer", "Coffee protects smokers from lung cancer", "The sample was too large", "Lung cancer causes people to drink coffee"], answer: 0, explanation: `${f(M.pctOf(CO.strata[0].coffee.n, CO.crude.coffee.n), 1)} % of coffee drinkers smoked, against ${f(M.pctOf(CO.strata[0].none.n, CO.crude.none.n), 1)} % of non-drinkers. Within smokers (9.0 v 9.0 per 1000) and non-smokers (1.0 v 1.0) there is no difference.` },
        ] },
      { id: "sample", label: "Sample size", tag: "hypothetical", title: "Physical activity and CHD: a small and a large study (hypothetical)",
        intro: "Two hypothetical cohort studies asked the same question: are physically active adults less likely to develop CHD over 10 years? Use 'add one case' to see how much each result depends on a single person.",
        questions: [
          { id: `q-${R}-iv11`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Sample size data (hypothetical). Adding one CHD case to the active group changes Study S's relative risk from 0.50 to 0.75, but hardly changes Study L's. What does this show?", options: ["Results from small samples are much less reliable: one person can change the conclusion", "Study S must contain errors", "Study L is wrong because it is too large", "Relative risk cannot be calculated for small studies"], answer: 0, explanation: `Study S has only ${SA.small.active.n} people in each group, so each case is ${f(100 / SA.small.active.n, 0)} % of a group. In Study L one case changes the active group's rate by less than 0.01 percentage points.` },
          { id: `q-${R}-iv12`, ref: R, stmts: S(3, 2), type: "short", marks: 3, stem: `Sample size data (hypothetical). Study L found CHD in ${f(sL.a, 1)} % of active and ${f(sL.i, 1)} % of inactive adults. Calculate the relative risk for active adults (2 d.p.) and give two reasons why the study does not show that physical activity prevents CHD. (3 marks)`, scheme: [{ point: `Relative risk = ${f(sL.a, 1)} ÷ ${f(sL.i, 1)} = ${f(sL.a / sL.i, 2)}`, marks: 1 }, { point: "Observational: active people may differ in other ways (confounders such as smoking, diet, weight, income)", marks: 1 }, { point: "Reverse causation (people with early heart problems may be less active) / activity self-reported / association does not show cause", marks: 1 }], model: `Relative risk = ${f(sL.a, 1)} ÷ ${f(sL.i, 1)} = ${f(sL.a / sL.i, 2)}, so active adults had about ${f(100 - 100 * sL.a / sL.i, 0)} % lower risk. This is an observational study, so it shows an association: active adults may also smoke less, eat differently or weigh less, and these confounders could explain some of the difference. People with early, undiagnosed heart disease may be less active (reverse causation), and activity may have been self-reported inaccurately.`, commonErrors: "Dividing the inactive value by the active value; saying a large sample proves cause." },
        ] },
    ] };

  // ---------------------------------------------------------------- D. Epidemiology Challenge ----------------------------------------------------------------
  const ratingScheme = (claimPoint, evidencePoint, limitPoint) => [{ point: claimPoint, marks: 1 }, { point: evidencePoint, marks: 1 }, { point: limitPoint, marks: 1 }];
  const epi = { kind: "disEpi", title: "Epidemiology Challenge", note: "Six claims of the kind you meet in the news and in exam questions. Read the evidence (real data are sourced; hypothetical data are labelled), decide how well the evidence supports the claim, then answer the questions. Each claim has a best judgement, and for two of them (Scenarios 3 and 4) a second judgement can also be defended. Judge only the evidence shown, not what you know from elsewhere.",
    ratings: [{ k: "sup", label: "Supported by this evidence" }, { k: "part", label: "Partly supported: some of it goes beyond the evidence" }, { k: "not", label: "Not supported by this evidence" }],
    items: [
      { id: "grandad", label: "My grandfather", tag: "real", title: "Scenario 1. 'My grandfather smoked all his life and lived to 90'",
        context: "A student argues: 'My grandfather smoked 20 a day from the age of 18 and lived to 90, so smoking cannot be that harmful.'",
        evidence: `<p>In the British doctors study, among ${D.survival.cohort}, <strong>${D.survival.smokers} %</strong> of men who continued smoking cigarettes survived from age ${D.survival.ages}, compared with <strong>${D.survival.never} %</strong> of lifelong non-smokers. ${cite("doll")}</p>`,
        claim: "Smoking cannot be very harmful, because some smokers live to old age.", best: "not",
        fb: { sup: "One person's outcome cannot outweigh data from thousands of people.", part: "It is true that some smokers live long lives, but that does not show smoking is not harmful.", not: `Correct. Risk describes probability in a population. ${D.survival.smokers} % of continuing smokers survived from 35 to 70, so some smokers do live long lives; but far more smokers than non-smokers died before 70 (${100 - D.survival.smokers} % v ${100 - D.survival.never} %).` },
        questions: [
          { id: `q-${R}-ep1`, ref: R, stmts: S(3), type: "short", marks: 3, stem: "Scenario 1. Use the data to explain why the grandfather's long life does not show that smoking is safe. (3 marks)", scheme: ratingScheme("A risk factor increases the probability of disease / death; it does not make it certain for an individual", `Uses data: ${D.survival.smokers} % of smokers v ${D.survival.never} % of non-smokers survived from 35 to 70, so many smokers do survive but a larger proportion die earlier`, "One case (an anecdote) cannot be generalised / population data cannot predict one person's outcome; other factors also affect lifespan"), model: `A risk factor raises the probability of disease or early death across a population; it does not decide what happens to each person. In the British doctors study, ${D.survival.smokers} % of continuing smokers born in the 1920s survived from 35 to 70, so many smokers do reach old age, but ${D.survival.never} % of non-smokers did, so smokers were much more likely to die early (${100 - D.survival.smokers} % against ${100 - D.survival.never} %). One grandfather is a single case and other factors (other risk factors, chance) also affect lifespan, so his long life does not show that smoking is safe.`, commonErrors: "Saying the grandfather must have been lying; saying all smokers die young." },
        ] },
      { id: "meat", label: "Processed meat", tag: "real", title: "Scenario 2. 'Bacon is as dangerous as cigarettes'",
        context: "In 2015 the International Agency for Research on Cancer (IARC) placed processed meat in the same group (Group 1, 'carcinogenic to humans') as tobacco smoking. A headline said: 'Bacon as dangerous as cigarettes'.",
        evidence: `<ul class="small"><li>IARC: each 50 g of processed meat eaten daily is associated with an ${M.IARC.pct} % higher risk of bowel (colorectal) cancer. ${cite("iarc")}</li><li>UK Biobank (${M.BIOBANK.people} adults aged ${M.BIOBANK.ages}, followed for ${M.BIOBANK.years}; ${M.BIOBANK.cases.toLocaleString("en-GB")} developed bowel cancer): people eating about ${M.BIOBANK.high} g of red and processed meat a day had about a 20 % higher risk than those eating about ${M.BIOBANK.low} g. ${cite("biobank")}</li><li>British doctors: current smokers' lung cancer death rate was ${lungRR} times that of lifelong non-smokers (${cu.lung} v ${nv.lung} per 1000 per year). ${cite("doll")}</li><li>The IARC groups describe the <strong>strength of the evidence</strong> that something can cause cancer, not <strong>how much</strong> it increases the risk.</li></ul>`,
        claim: "Eating processed meat is as dangerous as smoking.", best: "not",
        fb: { sup: "Being in the same evidence group does not mean the same size of risk.", part: "There is good evidence that processed meat increases bowel cancer risk, but the claim compares sizes of risk, and the sizes are very different.", not: `Correct. Both are classed as causes of cancer because the evidence is strong, but the size of the effect differs enormously: about a 1.2-fold risk of developing bowel cancer against about a ${lungRR}-fold death rate from lung cancer in smokers. Strictly these are different measures (the risk of developing a cancer, and the rate of dying from one), so the comparison is approximate, but the gap is far too large to be explained by that.` },
        questions: [
          { id: `q-${R}-ep2`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Scenario 2. Why is it misleading to say that processed meat is 'as dangerous as' smoking because they are in the same IARC group?", options: ["The groups describe how strong the evidence of a cancer link is, not how large the increase in risk is", "Processed meat is not linked to any cancer", "Smoking is not linked to cancer", "The UK Biobank study had too few people to detect any effect"], answer: 0, explanation: `The sizes of risk differ greatly: about 1.18 to 1.2 times the risk of developing bowel cancer, against a lung cancer death rate ${lungRR} times higher in smokers. These are different measures (incidence of a cancer and death rate from one), so the comparison is approximate, but the difference is far too large to be explained by that.` },
          { id: `q-${R}-ep3`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: `Scenario 2. Relative v absolute risk (HYPOTHETICAL illustration). Suppose that, without processed meat, ${RA.base} people in every ${RA.per} develop bowel cancer during their lives, and that a habit increases this risk by ${M.IARC.pct} % (relative risk ${RA.rr}).`, text: `Number per ${RA.per} with the habit: {{1}}. Absolute increase: {{2}} per ${RA.per}.`, answers: { 1: [String(raE)], 2: [String(raE - RA.base)] }, explanation: `${RA.base} × ${RA.rr} = ${f(RA.base * RA.rr, 0)}; ${raE} − ${RA.base} = ${raE - RA.base} more people per ${RA.per}. An ${M.IARC.pct} % relative increase is a ${raE - RA.base} in ${RA.per} absolute increase here.` },
        ] },
      { id: "gym", label: "Gym membership", tag: "hypothetical", title: "Scenario 3. 'Joining a gym cuts heart disease by 40 %'",
        context: "A gym chain advertises: 'Our members are 40 % less likely to develop heart disease. Join today and cut your risk!'",
        evidence: `<p>${HYP} A cohort followed ${G.members.n.toLocaleString("en-GB")} gym members and ${G.non.n.toLocaleString("en-GB")} non-members for ${G.years} years. CHD developed in ${G.members.cases} members (${f(gM, 1)} %) and ${G.non.cases} non-members (${f(gN, 1)} %). ${G.members.smoke} % of members smoked, against ${G.non.smoke} % of non-members; members also had higher average incomes.</p>`,
        claim: "Joining a gym will reduce your risk of heart disease by 40 %.", best: "part", accept: ["part", "not"],
        fb: { sup: "The 40 % figure is correct for this comparison, but 'joining will reduce your risk' is a causal claim about an individual that the data cannot support.", part: `Good. The association is real in these data (${f(gM, 1)} % v ${f(gN, 1)} %, a relative risk of ${f(gM / gN, 2)}), but members smoked less and were richer (confounders), people who join gyms may already be healthier, and the absolute difference is only ${f(gN - gM, 1)} percentage points over ${G.years} years.`, not: `Also defensible: as a causal claim about what joining will do for you, it is not supported, because members differed in smoking (${G.members.smoke} % v ${G.non.smoke} %) and income. The data do show an association.` },
        questions: [
          { id: `q-${R}-ep4`, ref: R, stmts: S(3), type: "short", marks: 4, stem: "Scenario 3 (hypothetical). Evaluate the advertisement's claim. (4 marks)", scheme: [{ point: `Calculation: ${f(gM, 1)} ÷ ${f(gN, 1)} = ${f(gM / gN, 2)}, i.e. 40 % lower (relative) risk, so the figure matches the data`, marks: 1 }, { point: `Absolute difference is small: ${f(gN - gM, 1)} percentage points (${f(10 * (gN - gM), 0)} per 1000) over ${G.years} years`, marks: 1 }, { point: `Confounding: members smoked less (${G.members.smoke} % v ${G.non.smoke} %) and had higher incomes; healthier people may choose to join`, marks: 1 }, { point: "Observational association, not proof of cause; cannot predict an individual's risk / does not show how often members exercised", marks: 1 }], model: `Members had a CHD rate of ${f(gM, 1)} % against ${f(gN, 1)} % for non-members, a relative risk of ${f(gM / gN, 2)}, so the '40 % less likely' figure is arithmetically correct. But the absolute difference is only ${f(gN - gM, 1)} percentage points, about ${f(10 * (gN - gM), 0)} fewer cases per 1000 people over ${G.years} years. More importantly, the groups differ in other ways: fewer members smoked (${G.members.smoke} % against ${G.non.smoke} %) and they were richer, and people who join gyms may already be healthier. These confounders could explain some or all of the difference. The study is observational and does not show that joining causes the reduction, nor what will happen to one person who joins.`, commonErrors: "Accepting the 40 % without considering the absolute difference; ignoring the smoking difference." },
        ] },
      { id: "salt", label: "Countries and salt", tag: "hypothetical", title: "Scenario 4. Salt and CHD across countries",
        context: "A report plots average salt intake against CHD death rate for six countries and finds that countries with higher salt intake have higher CHD death rates.",
        evidence: `<p>${HYP} Six fictional countries (scatter graph below). Each point is a whole country's average, not an individual.</p><div class="figure"><div class="fig-view">${A.saltScatter()}</div></div>`,
        claim: "People who eat more salt are more likely to die of CHD.", best: "not", accept: ["not", "part"],
        fb: { sup: "The data are about countries, not individuals, and the countries differ in many ways.", part: "There is a clear positive correlation between country averages, which is consistent with the claim and worth investigating. But the claim is about individual people, and data for whole countries cannot show that the individuals who eat more salt are the ones who die of CHD (the ecological fallacy). The countries may also differ in age structure, smoking, diet and health care. On this evidence alone, the claim about individuals is not supported.", not: "Correct. The claim is about individual people, but each point is a whole country's average, so these data cannot show that the individuals who eat more salt are the ones who die of CHD (the ecological fallacy), and the countries may differ in age structure, smoking, diet and health care. Other kinds of study, which measure salt intake and blood pressure in individual people, do link a high salt intake to raised blood pressure, a risk factor for CHD. That evidence is not shown here, and the rating asks only about this evidence." },
        questions: [
          { id: `q-${R}-ep5`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Scenario 4 (hypothetical). What is the main limitation of using these data to draw conclusions about individuals?", options: ["Each point is a country average: the people who eat most salt are not necessarily the people who die of CHD", "Six points are too few to draw a graph", "Salt cannot affect blood pressure", "The correlation is negative"], answer: 0, explanation: "This is the ecological fallacy; countries also differ in many confounding factors." },
        ] },
      { id: "bp", label: "Blood pressure", tag: "real", title: "Scenario 5. Blood pressure and IHD deaths",
        context: "A doctor tells a 55-year-old patient that people with higher blood pressure tend to have higher death rates from ischaemic heart disease (IHD).",
        evidence: `<p>A meta-analysis of individual data for ${M.LEWINGTON.adults} adults in ${M.LEWINGTON.studies} prospective studies (about ${M.LEWINGTON.ihdDeaths.toLocaleString("en-GB")} IHD deaths): ${M.LEWINGTON.statement} ${cite("lewington")}</p>`,
        claim: "In middle age, people with higher blood pressure tend to have higher death rates from IHD.", best: "sup",
        fb: { sup: "Correct. The claim is about a tendency across a population, which is exactly what this very large set of prospective studies measured.", part: "The claim is carefully worded: 'tend to have higher death rates' is a population association, which the data show directly.", not: "The data show this association very clearly, in a million adults; the claim does not say that blood pressure is the only factor or that every person will be affected." },
        questions: [
          { id: `q-${R}-ep6`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Scenario 5. Which statement goes BEYOND what this evidence shows?", options: ["Lowering this patient's blood pressure by 20 mm Hg will exactly halve his risk of dying from IHD", "IHD death rates were about twice as high for each 20 mm Hg higher usual systolic pressure at ages 40–69", "The association was found in data from many prospective studies", "No threshold was seen down to at least 115/75 mm Hg"], answer: 0, explanation: "The data describe an association across populations; predicting an exact change for one person, and assuming that lowering pressure reverses the risk fully, needs other evidence (such as trials) and ignores his other risk factors." },
        ] },
      { id: "quit", label: "Stopping smoking", tag: "real", title: "Scenario 6. Is it worth stopping?",
        context: "A 50-year-old man who has smoked since he was a teenager says there is no point stopping now, because the damage is done.",
        evidence: `<p>For UK men at 1990 rates, the cumulative risk of death from lung cancer by age 75 was ${PR.map((r) => `${r.risk.toFixed(1)} % (${r.label.toLowerCase()})`).join(", ")}. ${M.PETO.neverNote} ${cite("peto")} In the British doctors study, men who stopped at about 50 gained about 6 years of life expectancy compared with those who continued. ${cite("doll")}</p>`,
        claim: "For men like him, stopping at 50 was associated with a substantially lower risk of dying from lung cancer than continuing to smoke.", best: "sup",
        fb: { sup: `Correct. The estimated risk falls from ${cont} % to ${PR[2].risk.toFixed(1)} %, a ${red(2)} % relative reduction, though it stays well above that of lifelong non-smokers.`, part: "The claim is worded as an association for men like him, which is what the data show.", not: `The data directly contradict 'no point stopping': ${PR[2].risk.toFixed(1)} % against ${cont} %.` },
        questions: [
          { id: `q-${R}-ep7`, ref: R, stmts: S(2, 3), type: "short", marks: 3, stem: "Scenario 6. Use the data to advise the man, and state one limitation of applying the data to him. (3 marks)", scheme: ratingScheme(`Stopping at about 50 is associated with a lower risk: ${PR[2].risk.toFixed(1)} % v ${cont} % by age 75`, `A ${red(2)} % relative reduction / ${absd(2)} percentage points; also about 6 years of life expectancy gained (Doll)`, "Limitation: population estimates for UK men at 1990 rates; his own risk depends on how much he smoked and other factors; risk stays above non-smokers'"), model: `The data suggest stopping is worthwhile: UK men who stopped at about 50 had an estimated ${PR[2].risk.toFixed(1)} % risk of dying from lung cancer by 75, against ${cont} % for those who continued, a ${red(2)} % relative reduction (${absd(2)} percentage points), and the British doctors who stopped at about 50 gained about 6 years of life expectancy. However, these are population estimates for UK men at 1990 rates; his own risk depends on how much he has smoked and on other factors, and it will remain higher than that of a lifelong non-smoker.`, commonErrors: "Saying stopping removes the risk completely." },
        ] },
    ] };

  window.BIO.content[R] = {
    status: "draft",
    banner: "atheroma-lm", bannerText: "Coronary heart disease and cancers are not caught from other people. Their risk is shaped by many factors, some of which can be changed, and the evidence comes from studying large populations.",
    keywords: ["risk factor", "coronary heart disease", "CHD", "cancer", "lifestyle", "smoking", "blood pressure", "blood cholesterol", "diet", "obesity", "physical activity", "alcohol", "UV radiation", "incidence", "mortality rate", "rate per 100,000", "relative risk", "absolute risk", "odds ratio", "cohort study", "case-control study", "ecological study", "correlation", "causation", "confounding", "dose–response", "sample size", "bias", "British doctors study", "INTERHEART"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.1.2).</strong> <strong>Specific risk factors are associated with coronary heart disease and cancer.</strong> <strong>Changes in lifestyle may be associated with a reduced risk</strong> of contracting these conditions. You must be able to <strong>analyse, interpret and evaluate data</strong> associated with specific risk factors and the incidence of disease. The structure of atheroma is in 3.2.7 and the biology of tumours in 3.2.11; here they are cross-references only. Labels: <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span> ${SC} beyond the specification: an example to show the idea, not something to learn (named infections such as HPV are stretch and challenge; the specification names only cholera and HIV as diseases caused by pathogens).</div>

<h2 data-stmt="${R}.s1">1. Risk factors and non-infectious disease <span class="badge teal">required</span></h2>
<p>Coronary heart disease (CHD) and cancers are <strong>non-infectious</strong>: they are not caused by a pathogen passed from person to person (compare 3.2.1.1). They are among the leading causes of death worldwide: the World Health Organization estimates that <strong>${M.WHO.deathsM} million</strong> people died from cardiovascular diseases in ${M.WHO.year}, about <strong>${M.WHO.pctGlobal} %</strong> of all deaths, and ${M.WHO.pctAttackStroke} % of these were due to heart attacks and strokes. ${cite("who")}</p>
<ul><li>A <strong>risk factor</strong> is anything that <strong>increases the probability</strong> (the chance) that a person will develop a disease. It does not make the disease certain, and its absence does not guarantee good health.</li>
<li>Risk factors are <strong>associated</strong> with a disease: people with the factor develop the disease more often. Whether the factor <strong>causes</strong> the disease is a separate question that needs further evidence (section 6).</li>
<li>CHD and cancers are <strong>multifactorial</strong>: each has many risk factors, which add to or interact with one another. No disease here has a single risk factor.</li>
<li>Some risk factors can be changed (<strong>modifiable</strong>: smoking, diet, physical activity, body mass, alcohol, sun exposure); others cannot (<strong>non-modifiable</strong>: age, sex, inherited factors). <span class="badge">supporting</span> Inherited differences in genes are one reason why people with the same lifestyle differ in risk; the genetics of these diseases is not required here.</li></ul>
<div class="figure"><div class="fig-view">${A.riskWebFig()}</div></div>

<h2 data-stmt="${R}.s1">2. Risk factors for coronary heart disease <span class="badge teal">required</span></h2>
<p>CHD is disease of the coronary arteries, which supply the heart muscle. <span class="badge">supporting</span> Fatty material (atheroma) builds up in the artery walls and narrows them; if a coronary artery is blocked, part of the heart muscle is starved of oxygen (a heart attack). The details are in 3.2.7.</p>
${tbl(["Risk factor", "Notes"], [["Smoking", "Associated with damage to artery linings and raised blood pressure; one of the strongest modifiable risk factors"], ["High blood pressure", "Higher pressure is associated with more damage to artery walls; IHD death rates roughly double with each 20 mm Hg higher usual systolic pressure in middle age (see below)"], ["High blood cholesterol (LDL)", "Associated with more atheroma; linked to diet, especially saturated fat, and to inherited factors"], ["Diet", "High saturated fat and high salt (raises blood pressure) are associated with higher risk; daily fruit and vegetables with lower risk"], ["Physical inactivity, obesity, diabetes, excess alcohol", "Each associated with higher risk, partly through blood pressure, cholesterol and blood glucose"], ["Age, sex, family history", "Not modifiable: risk rises with age; men tend to develop CHD at younger ages; a family history raises risk <span class='badge'>supporting</span>"]])}
<p><strong>Real evidence: INTERHEART</strong> ${REAL("interheart")}. This case-control study compared ${M.INTERHEART.cases.toLocaleString("en-GB")} people after a first heart attack with ${M.INTERHEART.controls.toLocaleString("en-GB")} controls in ${M.INTERHEART.countries} countries. Odds ratios above 1 mean a factor was more common in people who had had a heart attack. Together, nine potentially modifiable factors accounted for about ${M.INTERHEART.combinedPAR.men} % of the population risk in men and ${M.INTERHEART.combinedPAR.women} % in women. The chart shows eight of them. ${M.INTERHEART.unplotted}</p>
<div class="figure"><div class="fig-view">${A.orChart()}</div></div>
<p><strong>Real evidence: blood pressure</strong> ${REAL("lewington")}. ${M.LEWINGTON.statement}</p>

<h2 data-stmt="${R}.s1">3. Risk factors for cancer <span class="badge teal">required</span></h2>
<p>Cancers are diseases in which cells divide uncontrollably (the biology is in 3.2.11). Different cancers have different risk factors:</p>
${tbl(["Risk factor", "Cancers most strongly associated (examples)"], [["Smoking (tobacco)", "Lung; also mouth, throat, oesophagus, bladder, pancreas and others"], ["Overweight and obesity", "Bowel, breast (after the menopause), womb, kidney, oesophagus and others"], ["Ultraviolet (UV) radiation from the Sun or sunbeds", "Skin cancers, including melanoma"], ["Alcohol", "Mouth, throat, oesophagus, breast, liver, bowel"], ["Diet: processed meat, low fibre", "Bowel"], ["Some infections", `${SC} Cervical cancer (human papillomavirus, HPV); stomach cancer (<em>Helicobacter pylori</em>); liver cancer (hepatitis B and C viruses)`], ["Ionising radiation; some workplace chemicals", "Leukaemia and others; lung (asbestos)"], ["Age; inherited factors", "Most cancers become more common with age; some inherited gene variants raise the risk of particular cancers <span class='badge'>supporting</span>"]])}
<p><strong>Real evidence: how much cancer is linked to modifiable factors?</strong> ${REAL("brown")}. In the UK in ${M.BROWN.year}, about <strong>${M.BROWN.all} %</strong> of cancer cases were attributable to known modifiable risk factors. The largest were <strong>tobacco smoking (${M.BROWN.tobacco} %)</strong> and <strong>overweight and obesity (${M.BROWN.obesity} %)</strong>, followed by UV radiation and occupational risks (${M.BROWN.uv} % each). For lung cancer, <strong>${M.BROWN.lungTobacco} %</strong> of cases were attributable to smoking: so most, but not all, lung cancers are linked to smoking. <span class="badge">supporting</span> These "attributable fractions" estimate how many cases would not have occurred without the risk factor; they are modelled from many studies, not counted directly.</p>

<h2 data-stmt="${R}.s2">4. Lifestyle changes and reduced risk <span class="badge teal">required</span></h2>
<p>The specification says changes in lifestyle <strong>may be associated with</strong> a reduced risk. The careful wording matters: most of the evidence comes from comparing groups of people, so it shows that people who change tend to have lower risk, and the size of any benefit for one person is uncertain.</p>
<ul><li><strong>Stopping smoking</strong>: associated with lower risk of lung and other cancers and of CHD; the earlier the better (data below).</li>
<li><strong>Diet</strong>: less saturated fat and salt, more fruit, vegetables and fibre; less processed meat.</li>
<li><strong>Physical activity</strong> and keeping a healthy body mass.</li>
<li><strong>Limiting alcohol</strong>; <strong>protecting skin from UV</strong> (shade, clothing, sunscreen; avoiding sunbeds).</li>
<li><span class="badge">supporting</span> Some reductions in risk come from medical measures rather than lifestyle, for example vaccination against HPV ${SC} or treatment of high blood pressure.</li></ul>
<p><strong>Real evidence: stopping smoking</strong> ${REAL("peto")}. ${M.PETO.neverNote}</p>
<div class="figure"><div class="fig-view">${A.petoChart()}</div></div>
<p>In the British doctors study, men who stopped at about 60, 50, 40 or 30 gained, respectively, about 3, 6, 9 or 10 years of life expectancy compared with those who continued. ${cite("doll")}</p>

<h2 data-stmt="${R}.s3">5. Analysing data on risk factors and incidence <span class="badge teal">required</span></h2>
<h3>Measures you need</h3>
<ul><li><strong>Incidence</strong>: the number of <em>new</em> cases in a population in a given time, usually given as a <strong>rate</strong> (per 1000 or per 100,000 people per year) so that populations of different sizes can be compared. <strong>Mortality rate</strong>: deaths per 1000 or 100,000 per year. <span class="badge">supporting</span> Prevalence is the number of people who have the disease at one time.</li>
<li>Rate = (number of cases ÷ number of people) × 1000 (or × 100,000). To convert a rate per 1000 to a rate per 100,000, multiply by 100.</li>
<li><strong>Percentage change</strong> = (new value − original value) ÷ original value × 100.</li>
<li><strong>Relative risk</strong> = risk (or rate) in the exposed group ÷ risk in the unexposed group. 1 = no difference; above 1 = higher risk; below 1 = lower risk. <span class="badge">supporting</span> Case-control studies give an <strong>odds ratio</strong>, which is read in the same way.</li>
<li><strong>Absolute risk difference</strong> = risk in the exposed group − risk in the unexposed group: how many extra cases per 1000 (or per 100) people.</li>
<li><strong>Age standardisation</strong> <span class="badge">supporting</span>: adjusting rates so that groups with different age structures can be compared fairly, because risk rises with age.</li></ul>
<div class="notice"><strong>Worked example: real data.</strong> ${REAL("doll")}<br>Age-standardised death rates per 1000 men per year, British doctors, ${D.period}:${dollTable()}
<ul class="small"><li>Lung cancer, relative: ${cu.lung} ÷ ${nv.lung} = <strong>${lungRR}</strong>: current smokers had about ${lungRR} times the death rate of lifelong non-smokers.</li>
<li>Lung cancer, absolute: ${cu.lung} − ${nv.lung} = <strong>${lungAbs}</strong> extra deaths per 1000 smokers per year (${Math.round(cu.lung * 100)} v ${Math.round(nv.lung * 100)} per 100,000).</li>
<li>IHD, relative: ${cu.ihd} ÷ ${nv.ihd} = <strong>${ihdRR}</strong> (a ${ihdPct} % increase). IHD, absolute: ${cu.ihd} − ${nv.ihd} = <strong>${ihdAbs}</strong> extra deaths per 1000 per year.</li>
<li>So smoking multiplies the lung cancer rate far more, but because IHD is much more common it adds <strong>more</strong> deaths from IHD than from lung cancer. Always ask which measure a claim is using.</li>
<li>Dose–response: lung cancer ${c1.lung}, ${c15.lung} and ${c25.lung} per 1000 for 1–14, 15–24 and 25 or more cigarettes a day (${dose} times as high at 25 or more as at 1–14).</li></ul></div>
<div class="figure"><div class="fig-view">${A.dollChart("lung")}</div></div>
<div class="figure"><div class="fig-view">${A.dollChart("ihd")}</div></div>
<h3>Relative and absolute risk</h3>
<p>A large <em>relative</em> increase in a rare disease can mean few extra cases; a small relative increase in a common disease can mean many. Headlines usually quote relative risk. ${HYP} In the illustration below, ${RA.base} in ${RA.per} people develop a disease without an exposure; the exposure has a relative risk of ${RA.rr} (the size of increase IARC gives for 50 g of processed meat a day and bowel cancer, ${cite("iarc")}), so ${raE} in ${RA.per} do. That is an ${M.IARC.pct} % relative increase but only ${raE - RA.base} extra cases per ${RA.per}.</p>
<div class="figure"><div class="fig-view">${A.relAbsFig()}</div></div>

<h2 data-stmt="${R}.s3 ${R}.s2">6. Evaluating evidence: association, correlation and cause <span class="badge teal">required</span></h2>
<h3>Types of study <span class="badge">supporting</span></h3>
${tbl(["Design", "What is done", "Example on this page", "Main limitations"], [["Cohort (prospective)", "A group is recorded and followed forward; incidence is compared between exposed and unexposed people", "British doctors; UK Biobank", "Long and costly; people choose their own exposures, so confounding remains"], ["Case-control", "People with the disease (cases) are compared with similar people without it (controls) for past exposures", "INTERHEART", "Exposure recalled or measured after the disease (recall bias); choice of controls matters"], ["Ecological", "Averages for whole populations (e.g. countries) are compared", "Salt and CHD (hypothetical)", "Cannot show that the individuals exposed are those who become ill; many differences between populations"], ["Randomised controlled trial", "Participants are randomly allocated to a treatment or a control", "Not used here: rarely possible for harmful exposures", "Ethical and practical limits; randomisation balances confounders"]])}
<h3>Correlation is not causation</h3>
<p>A <strong>correlation</strong> (or association) means two variables change together. It may arise because one causes the other, because a third factor affects both (<strong>confounding</strong>), because the disease affects the behaviour (<strong>reverse causation</strong>, for example people with early heart disease becoming less active), or by <strong>chance</strong>, especially in small samples. Evidence that makes cause more likely includes:</p>
<ul><li>a <strong>strong</strong> association (large relative risk);</li><li>a <strong>dose–response</strong> relationship (more exposure, more disease);</li><li>the exposure coming <strong>before</strong> the disease;</li><li><strong>consistent</strong> results from different studies, places and methods;</li><li>a plausible <strong>biological mechanism</strong> (for example, chemicals in tobacco smoke that damage DNA, 3.2.11);</li><li>risk <strong>falling when the exposure is removed</strong> (stopping smoking).</li></ul>
<h3>Confounding</h3>
<p>A <strong>confounder</strong> is a variable that is associated with the risk factor being studied and independently affects the risk of the disease, so it can create or hide an association. ${HYP}</p>
<div class="figure"><div class="fig-view">${A.confoundFig()}</div></div>
${tbl(["Group (hypothetical)", "Coffee drinkers: cases / people", "Rate per 1000", "Non-coffee drinkers: cases / people", "Rate per 1000"], [["Everyone", `${CO.crude.coffee.cases} / ${CO.crude.coffee.n.toLocaleString("en-GB")}`, f(crudeC, 1), `${CO.crude.none.cases} / ${CO.crude.none.n.toLocaleString("en-GB")}`, f(crudeN, 2)], ...CO.strata.map((s) => [s.label, `${s.coffee.cases} / ${s.coffee.n.toLocaleString("en-GB")}`, f(M.rate(s.coffee.cases, s.coffee.n), 1), `${s.none.cases} / ${s.none.n.toLocaleString("en-GB")}`, f(M.rate(s.none.cases, s.none.n), 1)])])}
<p>Overall, coffee drinkers appear to have ${f(crudeC / crudeN, 1)} times the rate of lung cancer. But ${f(M.pctOf(CO.strata[0].coffee.n, CO.crude.coffee.n), 0)} % of coffee drinkers smoke, against ${f(M.pctOf(CO.strata[0].none.n, CO.crude.none.n), 0)} % of non-drinkers. Within smokers and within non-smokers the rates are identical: the apparent effect of coffee is entirely due to smoking. Studies deal with confounding by matching groups, by analysing subgroups separately (as here) or by statistical adjustment.</p>
<h3>Sample size, representativeness and bias</h3>
<ul><li><strong>Sample size</strong>: small studies give unreliable rates; one or two cases can change the conclusion. Large studies (tens of thousands) give more precise estimates, but size alone does not remove confounding.</li>
<li><strong>Representativeness</strong>: the British doctors were all men and all doctors, so the results may not apply directly to women or to other populations; consistent results in other groups strengthen the conclusion.</li>
<li><strong>Bias</strong> <span class="badge">supporting</span>: exposures are often self-reported (smoking, diet, activity), and people may misremember or under-report them.</li></ul>
<h3>Population data and individuals</h3>
<p>Risk-factor data describe <strong>populations</strong>. They cannot tell you what will happen to one person: many smokers never develop lung cancer, and some non-smokers do. A relative risk of 2 means the disease is twice as common in the exposed group, not that every exposed person has twice the chance, because individuals differ in their other risk factors.</p>
<div class="notice amber"><strong>Checklist for evaluating a conclusion.</strong> (1) What exactly do the data show (quote values, with units)? (2) Is it relative or absolute risk, incidence or mortality? (3) What kind of study, how large, and who was studied? (4) Could confounding, reverse causation, bias or chance explain it? (5) Is there a dose–response, consistency with other studies, a mechanism, a fall in risk after the exposure is removed? (6) Does the conclusion go beyond the data (to cause, to other populations, to one individual)?</div>
${P("atheroma-lm")}
${SOURCES}`,
    diagrams: [
      { id: "d-3.2.1.2-1", title: "Risk factors for CHD and cancer", status: "reviewed", caption: "Main associations only: many risk factors are shared, each disease has many risk factors, and non-modifiable factors are marked with an asterisk. A risk factor raises the probability of disease; it does not make disease certain.", alt: "Two overlapping ovals labelled coronary heart disease and cancers. Left only: high blood pressure, high blood cholesterol, diabetes, being male. Overlap: smoking, unhealthy diet, overweight and obesity, physical inactivity, excess alcohol, increasing age, inherited factors. Right only: UV radiation, some infections such as HPV, ionising radiation, some workplace chemicals.", svg: A.riskWebFig() },
      { id: "d-3.2.1.2-2", title: "Smoking and lung cancer deaths (real data)", status: "reviewed", caption: `Age-standardised lung cancer death rate per 1000 men per year, male British doctors 1951–2001 (${SRC.doll.short}, Table 1). Note the dose–response among current smokers.`, alt: `Bar chart: ${D.rows.map((r) => `${r.label} ${r.lung}`).join("; ")} deaths per 1000 men per year.`, svg: A.dollChart("lung") },
      { id: "d-3.2.1.2-3", title: "Smoking and IHD deaths (real data)", status: "reviewed", caption: `Age-standardised ischaemic heart disease death rate per 1000 men per year, same study. The relative increase is smaller than for lung cancer, but the absolute increase is larger (${ihdAbs} v ${lungAbs} per 1000 per year).`, alt: `Bar chart: ${D.rows.map((r) => `${r.label} ${r.ihd}`).join("; ")} deaths per 1000 men per year.`, svg: A.dollChart("ihd") },
      { id: "d-3.2.1.2-4", title: "Stopping smoking and lung cancer risk (real data)", status: "reviewed", caption: `Cumulative risk of death from lung cancer by age 75 for UK men at 1990 rates (${SRC.peto.short}). ${M.PETO.neverNote}`, alt: `Bar chart: ${PR.map((r) => `${r.label} ${r.risk.toFixed(1)} %`).join("; ")}.`, svg: A.petoChart() },
      { id: "d-3.2.1.2-5", title: "Odds ratios for a first heart attack (real data)", status: "reviewed", caption: `INTERHEART case-control study (${SRC.interheart.short}). Odds ratios above 1 (red) mean the factor was more common in cases; below 1 (green) less common. The ApoB/ApoA1 ratio is a measure of blood lipids. ${M.INTERHEART.unplotted} Associations, not proof of cause.`, alt: `Dot chart of odds ratios: ${M.INTERHEART.rows.map((r) => `${r.label} ${r.or}`).join("; ")}, with a dashed line at 1.`, svg: A.orChart() },
      { id: "d-3.2.1.2-6", title: "Confounding", status: "reviewed", caption: "Smoking is associated with coffee drinking and causes lung cancer, so coffee drinking appears to be associated with lung cancer. Analysing smokers and non-smokers separately removes the apparent link (hypothetical data in the notes).", alt: "Three boxes: smoking at the top, coffee drinking bottom left, lung cancer bottom right. Arrows from smoking to both; a dashed arrow from coffee drinking to lung cancer labelled apparent link.", svg: A.confoundFig() },
      { id: "d-3.2.1.2-7", title: "Relative and absolute risk", status: "reviewed", caption: `Hypothetical illustration: ${RA.base} in ${RA.per} without the exposure, ${raE} in ${RA.per} with it. A relative risk of ${RA.rr} (an ${M.IARC.pct} % increase) is an absolute increase of ${raE - RA.base} in ${RA.per}.`, alt: `Two grids of 1000 small squares: ${RA.base} coloured on the left and ${raE} on the right.`, svg: A.relAbsFig() },
    ],
    interactives: [inv, epi],
    focus: [
      { slot: "atheroma-lm", title: "Inside a narrowed coronary artery", ref: R, explanation: () => `<p>A light micrograph of a section through a diseased artery shows the lumen narrowed by a thick, pale region within the wall: an atheroma (or plaque), containing lipids, including cholesterol, and other material. Atheroma builds up over decades, usually without symptoms, and its biology is studied in 3.2.7. What 3.2.1.2 asks is why some people develop it sooner and more severely than others. Large studies show that smoking, high blood pressure, high blood cholesterol, diabetes, physical inactivity and obesity are all associated with more coronary heart disease, and that the factors add together: a smoker with high blood pressure is at higher risk than someone with either factor alone. Age, sex and family history also matter and cannot be changed. Because most of this evidence comes from observing populations, the specification is careful to say that changes in lifestyle <em>may be associated</em> with reduced risk.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "A 45-year-old man smokes, has high blood pressure and takes little exercise; his father had a heart attack at 50. Identify which of his risk factors for CHD are modifiable, and suggest why changing them may be associated with, rather than guarantee, a reduced risk. (3 marks)", scheme: [{ point: "Modifiable: smoking, high blood pressure (through diet, exercise, or treatment), physical inactivity", marks: 1 }, { point: "Not modifiable: age, sex, family history (inherited factors)", marks: 1 }, { point: "Evidence comes from populations / associations; his risk still depends on unchangeable factors and chance, so the reduction for him cannot be guaranteed", marks: 1 }], model: "His smoking, high blood pressure and lack of exercise are modifiable: he can stop smoking, become more active and lower his blood pressure through diet, activity or treatment. His age, sex and family history cannot be changed. The evidence that these changes reduce risk comes from comparing groups of people, so it shows that people who make such changes tend to have lower risk; his own risk also depends on the factors he cannot change and on chance, so a reduction is likely but not guaranteed.", commonErrors: "Listing family history as modifiable; claiming changes will prevent a heart attack." } },
    ],
    examFocus: `<ul><li>Say "risk factor ... is <strong>associated</strong> with" or "increases the <strong>probability</strong> of", not "causes", unless the question gives evidence for cause.</li><li>Every disease here has <strong>several</strong> risk factors; do not write as if one factor explains a disease.</li><li>Data questions: quote values <strong>with units</strong>; calculate <strong>rates, percentages, percentage changes and ratios</strong>; show working; say whether you are comparing <strong>relative</strong> or <strong>absolute</strong> risk.</li><li>To evaluate a conclusion: what do the data show; type and size of study; who was studied; confounders, reverse causation, bias, chance; dose–response and consistency; does the conclusion go beyond the data?</li><li>Correlation does not prove cause. A confounder is linked to both the factor and the disease.</li><li>Population data cannot predict what happens to one person.</li><li>Lifestyle changes "<strong>may be associated with</strong> a reduced risk": use evidence such as the stopping-smoking data, and note limitations.</li></ul>`,
    synoptic: [
      { ref: "3.2.7.1", text: "Atheroma, aneurysm, thrombosis and myocardial infarction: the biology behind CHD." },
      { ref: "3.2.7.2", text: "Risk factors for CHD (diet, blood cholesterol, smoking, blood pressure) and data analysis." },
      { ref: "3.2.11.2", text: "Tumours, oncogenes and tumour suppressor genes; data on risk factors and particular cancers." },
      { ref: "3.2.1.1", text: "Infectious disease for contrast; infection (e.g. HPV) as a risk factor for some cancers." },
      { ref: "3.1.6", text: "Variation, sampling, sample size and interpreting data." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A risk factor for a disease is best described as something that:", options: ["increases the probability that a person will develop the disease", "always causes the disease in anyone exposed to it", "is the single cause of the disease", "only affects people who already have the disease"], answer: 0, explanation: "Risk is about probability across a population; most diseases here have many risk factors." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: `UK men who stopped smoking at about 40 had an estimated ${PR[3].risk.toFixed(1)} % risk of dying from lung cancer by 75, against ${cont} % for men who continued. Which statement is correct?`, options: ["Stopping at about 40 was associated with a much lower risk than continuing", "Stopping at 40 removed all extra risk", "The data prove that every man who stops at 40 will avoid lung cancer", "Stopping at 40 had no effect"], answer: 0, explanation: `${PR[3].risk.toFixed(1)} % against ${cont} %: a ${red(3)} % relative reduction. Lifelong non-smokers had a risk below 1 %.` },
      { id: `q-${R}-qc3`, ref: R, stmts: S(3), type: "gap", marks: 1, stem: "In a town of 40,000 people, 120 new cases of a cancer were diagnosed in one year.", text: "Incidence = {{1}} per 100,000 per year.", answers: { 1: [String(M.rate(120, 40000, 100000))] }, explanation: `120 ÷ 40,000 × 100,000 = ${M.rate(120, 40000, 100000)}.` },
      { id: `q-${R}-qc4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A study finds that people who carry lighters are more likely to develop lung cancer. What is the most likely explanation?", options: ["Smoking is a confounder: smokers are more likely to carry lighters", "Lighters cause lung cancer", "The study proves that lung cancer makes people carry lighters", "The association must be due to the sample being too large"], answer: 0, explanation: "A third variable linked to both carrying a lighter and lung cancer explains the correlation." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Studies show that smokers are much more likely to develop lung cancer than non-smokers. What can be concluded about a particular smoker?", options: ["Her probability of lung cancer is likely to be higher than if she did not smoke, but whether she develops it cannot be predicted", "She will develop lung cancer", "She will not develop lung cancer if she exercises", "Her risk is exactly the same as the average smoker's"], answer: 0, explanation: "Population data describe groups; individuals differ in their other risk factors and in chance." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "What is a risk factor?", back: "Anything that increases the probability of developing a disease. It is associated with the disease; it does not make it certain." },
      { id: `f-${R}-2`, front: "Why are CHD and cancer called non-infectious?", back: "They are not caused by a pathogen passed from person to person; many interacting factors affect risk." },
      { id: `f-${R}-3`, front: "Modifiable v non-modifiable risk factors.", back: "Modifiable: smoking, diet, physical activity, body mass, alcohol, UV exposure. Non-modifiable: age, sex, inherited (genetic) factors." },
      { id: `f-${R}-4`, front: "Main risk factors for CHD.", back: "Smoking, high blood pressure, high blood (LDL) cholesterol, diet high in saturated fat and salt, physical inactivity, obesity, diabetes, excess alcohol; also age, male sex, family history." },
      { id: `f-${R}-5`, front: "Main risk factors for cancer.", back: "Smoking, overweight/obesity, UV radiation, alcohol, diet (processed meat, low fibre), some infections (stretch and challenge examples: HPV, H. pylori, hepatitis B/C), ionising radiation, some chemicals; age; inherited factors." },
      { id: `f-${R}-6`, front: "Which infection is a risk factor for cervical cancer? (Stretch and challenge example.)", back: "Long-lasting infection with some types of human papillomavirus (HPV), which enters through the reproductive system." },
      { id: `f-${R}-7`, front: "UK 2015: share of cancer cases attributable to modifiable risk factors (Brown and others, 2018).", back: "About 37.7 %; largest: tobacco 15.1 %, overweight/obesity 6.3 %. 72.2 % of lung cancer cases attributable to smoking." },
      { id: `f-${R}-8`, front: "Lifestyle changes associated with reduced risk of CHD and cancer.", back: "Stopping smoking; less saturated fat, salt and processed meat; more fruit, vegetables and fibre; more physical activity; healthy body mass; less alcohol; UV protection." },
      { id: `f-${R}-9`, front: "Why does the specification say lifestyle changes 'may be associated with' reduced risk?", back: "Most evidence is from observational population studies: it shows association and probability, not a guaranteed benefit for an individual." },
      { id: `f-${R}-10`, front: "Stopping smoking (UK men, Peto and others, 2000): cumulative lung cancer death risk by 75.", back: "Continued 15.9 %; stopped at about 60: 9.9 %; 50: 6.0 %; 40: 3.0 %; 30: 1.7 %. Lifelong non-smokers below 1 %." },
      { id: `f-${R}-11`, front: "Define incidence.", back: "The number of new cases in a population in a given time, usually a rate per 1000 or per 100,000 people per year." },
      { id: `f-${R}-12`, front: "How do you calculate a rate per 100,000?", back: "(number of cases ÷ number of people) × 100,000. A rate per 1000 × 100 = rate per 100,000." },
      { id: `f-${R}-13`, front: "Relative risk v absolute risk difference.", back: "Relative risk = risk in exposed ÷ risk in unexposed. Absolute difference = risk in exposed − risk in unexposed (extra cases per 1000)." },
      { id: `f-${R}-14`, front: "British doctors: lung cancer and IHD death rates, current smokers v lifelong non-smokers.", back: `Lung cancer ${cu.lung} v ${nv.lung} per 1000 per year (${lungRR}×, +${lungAbs}); IHD ${cu.ihd} v ${nv.ihd} (${ihdRR}×, +${ihdAbs}). Bigger relative effect for lung cancer, more extra deaths from IHD.` },
      { id: `f-${R}-15`, front: "What does an odds ratio of 0.70 mean?", back: "The factor was associated with 30 % lower odds of the disease (e.g. daily fruit and vegetables and heart attack in INTERHEART)." },
      { id: `f-${R}-16`, front: "What is a confounder?", back: "A variable associated with the risk factor being studied that also independently affects the disease, so it can create or hide an apparent link (e.g. smoking, coffee and lung cancer)." },
      { id: `f-${R}-17`, front: "Evidence that makes a causal link more likely.", back: "Strong association; dose–response; exposure before disease; consistent results in many studies; plausible mechanism; risk falls when the exposure is removed." },
      { id: `f-${R}-18`, front: "Cohort v case-control study (supporting).", back: "Cohort: follow people forward and compare incidence (British doctors). Case-control: compare people with the disease and without for past exposures (INTERHEART)." },
      { id: `f-${R}-19`, front: "Why do sample size and representativeness matter?", back: "Small samples give unreliable results (one case can change the conclusion); an unrepresentative sample (e.g. only male doctors) may not apply to other groups." },
      { id: `f-${R}-20`, front: "Can population data predict an individual's risk?", back: "No. They give probabilities for groups; one person's outcome depends on their other risk factors and on chance." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which is NOT a modifiable risk factor for coronary heart disease?", options: ["Increasing age", "Smoking", "Physical inactivity", "A diet high in saturated fat"], answer: 0, explanation: "Age cannot be changed; the others can." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which risk factor is associated with both coronary heart disease and lung cancer?", options: ["Smoking", "UV radiation", "Human papillomavirus infection", "Asbestos only"], answer: 0, explanation: "Smoking is a major risk factor for both." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Exposure to ultraviolet radiation from the Sun and sunbeds is a risk factor mainly for:", options: ["skin cancers, including melanoma", "coronary heart disease", "cervical cancer", "bowel cancer"], answer: 0, explanation: "UV damages the DNA of skin cells (the mechanism is 3.2.11)." },
      { id: `q-${R}-m4`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Cervical cancer is not infectious, but infection with human papillomavirus (HPV) is a risk factor for it. Which statement is correct?", options: ["A non-infectious disease can have an infection as one of its risk factors", "Cervical cancer can be caught from another person in the same way as influenza", "HPV infection always leads to cervical cancer", "HPV is a bacterium"], answer: 0, explanation: "HPV is a virus; most infections clear and do not lead to cancer, but long-lasting infection with some types raises the risk." },
      { id: `q-${R}-m5`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which statement about risk factors for CHD is correct?", options: ["CHD has several risk factors, and a person can have more than one", "CHD has a single cause, high blood cholesterol", "People with no risk factors cannot develop CHD", "Risk factors for CHD are all inherited"], answer: 0, explanation: "CHD is multifactorial; risk factors add together." },
      { id: `q-${R}-m6`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which lifestyle change is most likely to be associated with a reduced risk of both CHD and several cancers?", options: ["Stopping smoking", "Increasing salt intake", "Using a sunbed", "Increasing intake of processed meat"], answer: 0, explanation: "Stopping smoking is associated with lower risk of lung and other cancers and of CHD." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "The specification says changes in lifestyle 'may be associated with' a reduced risk. Why is this wording used?", options: ["Most of the evidence shows associations in populations, so the benefit for an individual is a probability, not a certainty", "Lifestyle changes have never been shown to reduce risk", "Lifestyle changes always remove all risk", "Only inherited factors affect risk"], answer: 0, explanation: "Population evidence describes tendencies; individuals vary." },
      { id: `q-${R}-m8`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Incidence of a disease is:", options: ["the number of new cases in a population in a given period, often per 100,000 people per year", "the total number of people who have ever had the disease", "the number of deaths from the disease", "the proportion of patients who recover"], answer: 0, explanation: "Incidence counts new cases; mortality counts deaths." },
      { id: `q-${R}-m9`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: `In the British doctors study, the lung cancer death rate was ${cu.lung} per 1000 per year in current smokers and ${nv.lung} in lifelong non-smokers. What is the rate in current smokers per 100,000?`, options: [String(Math.round(cu.lung * 100)), f(cu.lung * 10, 1), String(Math.round(cu.lung * 1000)), Math.round(cu.lung * 100000).toLocaleString("en-GB")], answer: 0, explanation: `${cu.lung} × 100 = ${Math.round(cu.lung * 100)} per 100,000.` },
      { id: `q-${R}-m10`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: `Using the same study, current smokers' lung cancer death rate (${cu.lung}) divided by non-smokers' (${nv.lung}) is:`, options: [lungRR, lungAbs, f(nv.lung / cu.lung, 2), "249"], answer: 0, explanation: `${cu.lung} ÷ ${nv.lung} = ${lungRR}. ${lungAbs} is the difference; ${f(nv.lung / cu.lung, 2)} is the ratio upside down.` },
      { id: `q-${R}-m11`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: `In the British doctors study, lung cancer death rates were ${c1.lung}, ${c15.lung} and ${c25.lung} per 1000 per year for men smoking 1–14, 15–24 and 25 or more cigarettes a day. This pattern is called:`, options: ["a dose–response relationship", "a negative correlation", "confounding", "reverse causation"], answer: 0, explanation: "More exposure, more disease: one line of evidence supporting cause." },
      { id: `q-${R}-m12`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A confounding variable is one that:", options: ["is associated with the risk factor and independently affects the disease, creating or hiding an apparent link", "is deliberately changed by the investigator", "is always measured with no error", "has no effect on the disease"], answer: 0, explanation: "Confounders explain why correlation does not prove causation." },
      { id: `q-${R}-m13`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Two studies of the same risk factor give relative risks of 0.5 (50 people) and 0.62 (20,000 people). Which result is more reliable, and why?", options: ["The larger study, because each case has a much smaller effect on the estimate", "The smaller study, because the effect is bigger", "They are equally reliable because both are below 1", "Neither, because relative risks cannot be compared"], answer: 0, explanation: "Small samples are strongly affected by chance." },
      { id: `q-${R}-m14`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "A news report says a food 'doubles the risk' of a rare cancer, from 1 in 10,000 to 2 in 10,000 people. Which statement is correct?", options: ["The relative risk is 2, but the absolute increase is 1 extra case per 10,000 people", "The absolute risk has increased by 100 per 10,000", "Half of people who eat the food will develop the cancer", "The relative risk is 1"], answer: 0, explanation: "Relative risk 2 ÷ 1 = 2; absolute increase 2 − 1 = 1 per 10,000." },
      { id: `q-${R}-m15`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "People who already have early heart disease often become less physically active. Why might this affect a study linking inactivity to CHD?", options: ["It is reverse causation: the disease may cause the inactivity, exaggerating the apparent effect of inactivity", "It means inactivity cannot be associated with CHD", "It is an example of a dose–response relationship", "It shows that the sample was too large"], answer: 0, explanation: "Recording activity long before diagnosis, or excluding early cases, reduces this problem." },
      { id: `q-${R}-m16`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "An ecological study shows that countries with more cars per person have higher CHD death rates. Which is the best evaluation?", options: ["It is a correlation between country averages; many other differences between countries (diet, age, smoking, activity) could explain it", "It proves that cars cause CHD", "It shows that each car owner has a higher risk", "It is a randomised controlled trial"], answer: 0, explanation: "Ecological correlations cannot be applied to individuals and are prone to confounding." },
      { id: `q-${R}-m17`, ref: R, stmts: S(1, 3), type: "mcq", marks: 1, stem: `In the UK in 2015, about ${M.BROWN.lungTobacco} % of lung cancer cases were estimated to be attributable to smoking. Which statement follows?`, options: ["Most lung cancers are linked to smoking, but some occur in people who have never smoked or are due to other factors", "Every lung cancer is caused by smoking", `${M.BROWN.lungTobacco} % of smokers develop lung cancer`, "Smoking is not a risk factor for lung cancer"], answer: 0, explanation: "An attributable fraction refers to cases, not to the proportion of smokers who become ill." },
      { id: `q-${R}-m18`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Why are death rates in the British doctors study 'age-standardised'?", options: ["Smokers and non-smokers had different age structures, and risk of death rises with age, so standardisation allows a fair comparison", "To make the numbers smaller", "Because all the doctors were the same age", "To remove the effect of smoking"], answer: 0, explanation: "Age is a confounder for almost every disease; standardisation adjusts for it (supporting)." },
      // ---- gap fills ----
      { id: `q-${R}-g1`, ref: R, stmts: S(3), type: "gap", marks: 3, stem: `Real data (British doctors). IHD death rates were ${cu.ihd} per 1000 per year in current smokers and ${nv.ihd} in lifelong non-smokers.`, text: "Relative risk (2 d.p.): {{1}}. Percentage increase (1 d.p.): {{2}} %. Extra deaths per 1000 smokers per year (2 d.p.): {{3}}.", answers: { 1: [ihdRR], 2: [...new Set([ihdPct, ihdPct2, f(+ihdPct2, 0)])], 3: [ihdAbs] }, explanation: `${cu.ihd.toFixed(2)} ÷ ${nv.ihd.toFixed(2)} = ${ihdRR}; (${cu.ihd.toFixed(2)} − ${nv.ihd.toFixed(2)}) ÷ ${nv.ihd.toFixed(2)} × 100 = ${ihdPct} %; ${cu.ihd.toFixed(2)} − ${nv.ihd.toFixed(2)} = ${ihdAbs}. Working from the rounded relative risk (${ihdRR}) gives ${ihdPct2} %, which is also accepted, but it is better to calculate from the original rates.` },
      { id: `q-${R}-g2`, ref: R, stmts: S(2, 3), type: "gap", marks: 2, stem: `Real data (Peto and others). The cumulative risk of death from lung cancer by 75 was ${cont} % for UK men who continued smoking and ${PR[4].risk.toFixed(1)} % for those who stopped at about 30. Give answers to 1 d.p.`, text: "Absolute reduction: {{1}} percentage points. Relative reduction: {{2}} %.", answers: { 1: [absd(4)], 2: [red(4)] }, explanation: `${cont} − ${PR[4].risk.toFixed(1)} = ${absd(4)}; ${absd(4)} ÷ ${cont} × 100 = ${red(4)} %.` },
      { id: `q-${R}-g3`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: `Real data (WHO). An estimated ${M.WHO.deathsM} million people died from cardiovascular diseases in ${M.WHO.year}, and ${M.WHO.pctAttackStroke} % of these deaths were due to heart attacks and strokes.`, text: "Deaths from heart attacks and strokes: {{1}} million (1 d.p.). Deaths from other cardiovascular diseases: {{2}} million (1 d.p.).", answers: { 1: [whoAS], 2: [f(M.WHO.deathsM - +whoAS, 1), "3"] }, explanation: `${M.WHO.deathsM} × 0.${M.WHO.pctAttackStroke} = ${whoAS} million; ${M.WHO.deathsM} − ${whoAS} = ${f(M.WHO.deathsM - +whoAS, 1)} million.` },
      { id: `q-${R}-g4`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: `Hypothetical data. In a cohort, ${G.members.cases} of ${G.members.n.toLocaleString("en-GB")} gym members and ${G.non.cases} of ${G.non.n.toLocaleString("en-GB")} non-members developed CHD in ${G.years} years.`, text: "Percentage of members with CHD: {{1}} %. Relative risk for members (2 d.p.): {{2}}.", answers: { 1: [f(gM, 1), String(gM)], 2: [f(gM / gN, 2), f(gM / gN, 1)] }, explanation: `${G.members.cases} ÷ ${G.members.n} × 100 = ${f(gM, 1)} %; non-members ${f(gN, 1)} %; ${f(gM, 1)} ÷ ${f(gN, 1)} = ${f(gM / gN, 2)}.` },
      // ---- matching ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(1), type: "match", marks: 4, stem: "Match each risk factor to the condition it is most specifically associated with.", pairs: [{ left: "UV radiation", right: "Skin cancer, including melanoma" }, { left: "Long-lasting HPV infection (stretch and challenge)", right: "Cervical cancer" }, { left: "High blood pressure", right: "Coronary heart disease" }, { left: "Asbestos at work", right: "Cancers of the lung and its lining" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(3), type: "match", marks: 4, stem: "Match each term to its meaning.", pairs: [{ left: "Relative risk", right: "Risk in the exposed group divided by risk in the unexposed group" }, { left: "Absolute risk difference", right: "Extra cases per 1000 people in the exposed group compared with the unexposed" }, { left: "Confounder", right: "A third variable linked to both the exposure and the disease" }, { left: "Dose–response", right: "The more of the exposure, the higher the incidence" }] },
      // ---- short and data questions ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "Give two risk factors for CHD that are also risk factors for cancer, and describe a lifestyle change associated with reduced risk for each. (3 marks)", scheme: [{ point: "Two shared risk factors named, e.g. smoking, obesity / overweight, physical inactivity, excess alcohol, unhealthy diet", marks: 1 }, { point: "Change for the first: e.g. stop smoking", marks: 1 }, { point: "Change for the second: e.g. lose weight / be more physically active / drink less alcohol / eat more fruit, vegetables and fibre", marks: 1 }], model: "Smoking and obesity are risk factors for both CHD and several cancers. Stopping smoking is associated with a lower risk of lung and other cancers and of CHD. Losing weight through a healthier diet and more physical activity is associated with a lower risk of CHD and of cancers such as bowel cancer.", commonErrors: "Naming UV or high blood pressure as shared." },
      { id: `q-${R}-s2`, ref: R, stmts: S(3, 1), type: "short", marks: 4, stem: `Real data. ${dollTable()}Death rates per 1000 men per year, male British doctors 1951–2001 (age-standardised). Evaluate the conclusion that 'smoking causes lung cancer'. (4 marks)`, scheme: [{ point: `Data show a strong association: ${cu.lung} v ${nv.lung} per 1000 per year (about ${lungRR} times)`, marks: 1 }, { point: `Dose–response: ${c1.lung}, ${c15.lung}, ${c25.lung} for increasing cigarettes per day; former smokers lower (${fo.lung}) than current`, marks: 1 }, { point: "Large cohort followed forward over 50 years; exposure recorded before disease; age-standardised", marks: 1 }, { point: "Limitation: observational / possible confounding; only male doctors (representativeness); self-reported smoking; on its own shows association, but with mechanism and consistent studies cause is very likely", marks: 1 }], model: `The data show a strong association: current smokers had a lung cancer death rate of ${cu.lung} per 1000 per year against ${nv.lung} for lifelong non-smokers, about ${lungRR} times as high. There is a dose–response relationship (${c1.lung}, ${c15.lung} and ${c25.lung} per 1000 for 1–14, 15–24 and 25 or more a day), and former smokers had a lower rate (${fo.lung}) than current smokers. The study was large, followed men forward for 50 years with smoking recorded before death, and rates were standardised for age. However, it is observational, so confounding cannot be completely excluded; the participants were all male doctors, and smoking was self-reported. These data alone show association, but together with consistent results from other studies and a known mechanism they strongly support a causal link.`, commonErrors: "Saying the study proves cause by itself; ignoring the dose–response." },
      { id: `q-${R}-s3`, ref: R, stmts: S(3), type: "short", marks: 3, stem: `Real data. In the British doctors study, smoking raised the lung cancer death rate ${lungRR}-fold and the IHD death rate ${ihdRR}-fold. A student concludes that smoking is responsible for more extra lung cancer deaths than extra IHD deaths. Use the rates (lung cancer ${cu.lung} v ${nv.lung}; IHD ${cu.ihd} v ${nv.ihd} per 1000 per year) to evaluate this. (3 marks)`, scheme: [{ point: `Extra lung cancer deaths: ${cu.lung} − ${nv.lung} = ${lungAbs} per 1000 per year`, marks: 1 }, { point: `Extra IHD deaths: ${cu.ihd} − ${nv.ihd} = ${ihdAbs} per 1000 per year, which is more`, marks: 1 }, { point: "The conclusion is wrong: it confuses relative risk with absolute risk; IHD is much more common, so a smaller relative increase gives more extra deaths", marks: 1 }], model: `The extra lung cancer death rate in smokers is ${cu.lung} − ${nv.lung} = ${lungAbs} per 1000 per year, but the extra IHD death rate is ${cu.ihd} − ${nv.ihd} = ${ihdAbs} per 1000 per year. So the conclusion is wrong: the student has used relative risk, which is far higher for lung cancer, but because IHD is so much more common, its smaller relative increase adds more deaths.`, commonErrors: "Comparing only the ratios." },
      { id: `q-${R}-s4`, ref: R, stmts: S(3), type: "short", marks: 4, stem: `Hypothetical data. ${tbl(["Group", "Coffee drinkers: cases / people", "Non-coffee drinkers: cases / people"], [["Everyone", `${CO.crude.coffee.cases} / ${CO.crude.coffee.n.toLocaleString("en-GB")}`, `${CO.crude.none.cases} / ${CO.crude.none.n.toLocaleString("en-GB")}`], ...CO.strata.map((s) => [s.label, `${s.coffee.cases} / ${s.coffee.n.toLocaleString("en-GB")}`, `${s.none.cases} / ${s.none.n.toLocaleString("en-GB")}`])])}Lung cancer cases over 10 years. (a) Calculate the rate per 1000 in coffee drinkers and in non-coffee drinkers for everyone together. (1 mark) (b) Explain why the data do not show that coffee increases the risk of lung cancer. (3 marks)`, scheme: [{ point: `(a) ${f(crudeC, 1)} and ${f(crudeN, 2)} per 1000`, marks: 1 }, { point: "(b) Within smokers the rates are equal (9.0 v 9.0 per 1000) and within non-smokers equal (1.0 v 1.0)", marks: 1 }, { point: `(b) Coffee drinkers are much more likely to smoke (${f(M.pctOf(CO.strata[0].coffee.n, CO.crude.coffee.n), 0)} % v ${f(M.pctOf(CO.strata[0].none.n, CO.crude.none.n), 0)} %)`, marks: 1 }, { point: "(b) Smoking is a confounder: it is linked to coffee drinking and to lung cancer, so it creates the apparent link", marks: 1 }], model: `(a) Coffee drinkers: ${CO.crude.coffee.cases} ÷ ${CO.crude.coffee.n.toLocaleString("en-GB")} × 1000 = ${f(crudeC, 1)} per 1000; non-coffee drinkers: ${CO.crude.none.cases} ÷ ${CO.crude.none.n.toLocaleString("en-GB")} × 1000 = ${f(crudeN, 2)} per 1000. (b) When smokers and non-smokers are analysed separately, coffee makes no difference: 9.0 against 9.0 per 1000 in smokers and 1.0 against 1.0 in non-smokers. Most coffee drinkers smoke (${CO.strata[0].coffee.n} of ${CO.crude.coffee.n.toLocaleString("en-GB")}), but few non-drinkers do (${CO.strata[0].none.n} of ${CO.crude.none.n.toLocaleString("en-GB")}). Smoking is associated with coffee drinking and with lung cancer, so it is a confounder that creates the apparent link.`, commonErrors: "Concluding that coffee is harmful from the combined figures." },
      { id: `q-${R}-s5`, ref: R, stmts: S(3, 1), type: "short", marks: 3, stem: `Real data. INTERHEART compared ${M.INTERHEART.cases.toLocaleString("en-GB")} people who had had a first heart attack with ${M.INTERHEART.controls.toLocaleString("en-GB")} controls. The odds ratio for diabetes was 2.37 and for regular physical activity 0.86. (a) Interpret these two values. (2 marks) (b) Give one limitation of a case-control design. (1 mark)`, scheme: [{ point: "(a) Diabetes: odds of having had a heart attack about 2.4 times higher in people with diabetes", marks: 1 }, { point: "(a) Physical activity: about 14 % lower odds; associations, not proof of cause", marks: 1 }, { point: "(b) Exposure measured / recalled after the heart attack (recall bias, reverse causation) / controls may not be comparable / confounding", marks: 1 }], model: "(a) People with diabetes had about 2.4 times the odds of having had a heart attack compared with people without diabetes, while people who were regularly physically active had about 14 % lower odds. Both are associations. (b) In a case-control study, information about exposures is collected after the heart attack, so people may recall their past behaviour inaccurately, and the heart attack may itself have changed their behaviour.", commonErrors: "Reading 0.86 as an 86 % reduction." },
      { id: `q-${R}-s6`, ref: R, stmts: S(2, 3), type: "short", marks: 3, stem: `Real data. For UK men, the cumulative risk of death from lung cancer by 75 was ${PR.map((r) => `${r.risk.toFixed(1)} % (${r.label.toLowerCase()})`).join(", ")}. Describe what the data show and explain how they support advice to stop smoking as early as possible. (3 marks)`, scheme: [{ point: "Stopping at any of the ages was associated with lower risk than continuing", marks: 1 }, { point: `The earlier men stopped, the lower the risk (e.g. ${PR[4].risk.toFixed(1)} % at 30 v ${PR[1].risk.toFixed(1)} % at 60), quoting values`, marks: 1 }, { point: "So stopping early is associated with the greatest reduction; even late stopping reduces risk; but risk remains above that of non-smokers / population estimate", marks: 1 }], model: `Men who stopped smoking at any of the ages had a lower estimated risk than men who continued (${cont} %). The earlier they stopped, the lower the risk: ${PR[1].risk.toFixed(1)} % for stopping at about 60, ${PR[2].risk.toFixed(1)} % at 50, ${PR[3].risk.toFixed(1)} % at 40 and ${PR[4].risk.toFixed(1)} % at 30. So stopping as early as possible is associated with the largest reduction, although stopping later still helps; even early stoppers remain at higher risk than lifelong non-smokers, and these are estimates for a population.`, commonErrors: "Saying stopping at 30 gives zero risk." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2, 3), type: "extended", marks: 6, stem: "Extended response. Using named risk factors and the kinds of evidence on this page, discuss the extent to which lifestyle affects the risk of coronary heart disease and cancer. (6 marks)", scheme: [{ point: "Named risk factors for CHD (e.g. smoking, high blood pressure, high blood cholesterol, diet, inactivity, obesity, diabetes)", marks: 1 }, { point: "Named risk factors for cancer (e.g. smoking, obesity, UV, alcohol, processed meat, infections such as HPV)", marks: 1 }, { point: "Evidence quoted, e.g. British doctors: lung cancer 2.49 v 0.17 per 1000 per year; dose–response; or 37.7 % of UK cases attributable to modifiable factors", marks: 1 }, { point: "Lifestyle change associated with reduced risk, with evidence, e.g. stopping smoking at 50: 6.0 % v 15.9 % lung cancer risk by 75", marks: 1 }, { point: "Limits of the evidence: observational, confounding, reverse causation, self-report, representativeness; correlation v causation; relative v absolute risk", marks: 1 }, { point: "Balanced conclusion: lifestyle substantially affects risk across populations, but non-modifiable factors (age, sex, inherited factors) and chance also matter; individual risk cannot be predicted", marks: 1 }], levels: "Level 3 (5–6): risk factors for both conditions, quantitative evidence used accurately, limitations of evidence explained, and a balanced conclusion about populations and individuals. Level 2 (3–4): risk factors and some evidence or limitations, conclusion one-sided. Level 1 (1–2): a list of risk factors.", model: `Many lifestyle factors are associated with CHD and with cancer. For CHD these include smoking, high blood pressure, high blood cholesterol linked to a diet high in saturated fat, physical inactivity, obesity and diabetes; for cancers they include smoking, obesity, alcohol, UV exposure, processed meat and infections such as HPV. The evidence is strong for some factors: in the British doctors study, current smokers died of lung cancer at ${cu.lung} per 1000 per year against ${nv.lung} for lifelong non-smokers, with a dose–response relationship, and in the UK in ${M.BROWN.year} about ${M.BROWN.all} % of cancer cases were attributable to modifiable risk factors. Changing lifestyle is associated with lower risk: UK men who stopped smoking at about 50 had a ${PR[2].risk.toFixed(1)} % risk of dying from lung cancer by 75 against ${cont} % for those who continued. However, most of this evidence is observational: confounding (people who exercise may also smoke less), reverse causation and inaccurate self-reporting may affect results, and some samples, such as male doctors, are not representative. Relative risks can also exaggerate small absolute changes. Overall, lifestyle has a large effect on the risk of these diseases across populations, but age, sex, inherited factors and chance also matter, so the data cannot predict what will happen to any one person.`, commonErrors: "Listing risk factors with no evidence; claiming lifestyle is the only factor; treating associations as proof." },
      { id: `q-${R}-e2`, ref: R, stmts: S(3, 2), type: "extended", marks: 6, stem: "Extended response. A researcher wants to find out whether eating more fibre is associated with a lower risk of bowel cancer. Describe how a cohort study could investigate this and explain how the researcher should evaluate the results. (6 marks)", scheme: [{ point: "Recruit a large sample of people without bowel cancer; record fibre intake (e.g. food diaries / questionnaires) at the start", marks: 1 }, { point: "Follow them over many years and record new cases (incidence) of bowel cancer", marks: 1 }, { point: "Compare incidence (rate per 1000 or 100,000 per year) between groups with different fibre intakes; calculate relative risk / look for a dose–response", marks: 1 }, { point: "Record and adjust for confounders (age, sex, smoking, body mass, alcohol, processed meat, physical activity)", marks: 1 }, { point: "Evaluate: association not proof of cause; self-reported diet inaccurate; reverse causation (early symptoms change diet); representativeness", marks: 1 }, { point: "Consider sample size / chance, consistency with other studies, plausible mechanism, relative v absolute risk; cannot predict an individual's risk", marks: 1 }], levels: "Level 3 (5–6): a valid, prospective design with incidence compared, confounders controlled, and a reasoned evaluation including association v causation. Level 2 (3–4): design with gaps or a limited evaluation. Level 1 (1–2): fragments.", model: "The researcher should recruit a large group of adults who do not have bowel cancer and record their diets at the start, for example with food questionnaires or diaries, so that fibre intake is known before any disease develops. The group is followed for many years and new cases of bowel cancer are recorded. Incidence is calculated as a rate per 100,000 per year for people grouped by fibre intake, and the relative risk compared with the lowest-fibre group is calculated; a steady fall in incidence with increasing fibre would be a dose–response. Because people who eat more fibre may also smoke less, drink less, eat less processed meat, be more active and weigh less, these confounders must be recorded and adjusted for, along with age and sex. The results would show an association, not proof of cause: diet is self-reported and may change over time, early symptoms might change diet (reverse causation), and the sample may not represent everyone. Confidence that fibre reduces risk would be greater if the study was large, the association was consistent with other studies and a biological mechanism was known. Even then, the result is a population average and cannot predict an individual's risk, and absolute differences should be reported as well as relative ones.", commonErrors: "Describing an experiment that forces people to change diet without considering ethics; ignoring confounders." },
    ],
  };
})();
